// ---------- Content (generated by scripts/build-content.ts) ----------

export type Domain =
  | 'command-center' | 'cs-core' | 'system-design' | 'lld' | 'ai' | 'cybersecurity' | 'dsa'
  | 'career' | 'research' | 'academic' | 'developer' | 'patterns' | 'checklists' | 'adr'
  | 'projects' | 'prompts' | 'automation';

export type DocType =
  | 'concept' | 'pattern' | 'case-study' | 'problem' | 'roadmap' | 'checklist' | 'template'
  | 'playbook' | 'adr' | 'guide' | 'cheatsheet' | 'index' | 'tracker';

export type Difficulty = 'beginner' | 'intermediate' | 'advanced';
export type ContentStatus = 'evergreen' | 'draft' | 'todo';

export interface Heading {
  depth: number;
  text: string;
  id: string;
}

/** Metadata for one Markdown note. `Concept` is the generic name used across the app. */
export interface DocMeta {
  slug: string;
  title: string;
  description: string;
  domain: Domain | string;
  category: string;
  type: DocType | string;
  difficulty?: Difficulty | string;
  status: ContentStatus | string;
  tags: string[];
  prerequisites: string[];
  related: string[];
  order?: number;
  path: string;
  headings: Heading[];
  wordCount: number;
  taskCount: number;
  backlinks: string[];
  outgoing: string[];
  // type-specific
  pattern?: string;
  source?: string;
  languages?: string[];
  scale?: string;
  adr_status?: string;
  date?: string;
  role?: string;
}
export type Concept = DocMeta;

export interface DocPayload extends DocMeta {
  body: string;
  /** relative markdown link href -> resolved slug */
  linkMap: Record<string, string>;
}

export interface SearchEntry {
  slug: string;
  title: string;
  description: string;
  tags: string[];
  domain: string;
  type: string;
  text: string;
}

export interface GraphNode { id: string; title: string; domain: string; type: string }
export interface GraphEdge { source: string; target: string; kind: 'prerequisite' | 'related' | 'link' }
export interface GraphData { nodes: GraphNode[]; edges: GraphEdge[] }

// Semantic aliases over DocMeta for content-driven entities
export type Pattern = DocMeta & { type: 'pattern' };
export type SystemDesignCase = DocMeta & { type: 'case-study'; scale?: string };
export type DSAProblem = DocMeta & { type: 'problem'; pattern?: string; source?: string; languages?: string[] };
export type Roadmap = DocMeta & { type: 'roadmap'; role?: string };
export type Checklist = DocMeta & { type: 'checklist' };
export type ADR = DocMeta & { type: 'adr'; adr_status?: string; date?: string };

// ---------- User state (localStorage) ----------

export type DocProgress = 'not-started' | 'learning' | 'done' | 'revise';

export interface Resource { title: string; url: string }

export type ProjectStatus = 'idea' | 'active' | 'paused' | 'shipped' | 'archived';
export interface Project {
  id: string;
  name: string;
  objective: string;
  problem: string;
  stack: string;
  repo: string;
  milestones: string;
  status: ProjectStatus;
  maturity: 1 | 2 | 3 | 4 | 5;
  createdAt: string;
}

export type TaskStatus = 'todo' | 'doing' | 'done';
export interface Task { id: string; title: string; status: TaskStatus; due: string; area: string; createdAt: string }
export interface Goal { id: string; title: string; horizon: 'week' | 'month' | 'quarter' | 'year'; metric: string; status: 'open' | 'achieved' | 'dropped'; createdAt: string }
export interface Milestone { id: string; title: string; target: string; done: boolean; createdAt: string }
export interface Habit { id: string; name: string; cadence: 'daily' | 'weekly'; log: string[]; createdAt: string }
export interface JournalEntry { id: string; date: string; title: string; body: string; createdAt: string }
export interface Decision { id: string; date: string; title: string; context: string; decision: string; consequences: string; createdAt: string }
export interface Achievement { id: string; date: string; title: string; evidence: string; createdAt: string }

export type ApplicationStatus = 'wishlist' | 'applied' | 'oa' | 'interview' | 'offer' | 'rejected' | 'withdrawn';
export interface CareerApplication {
  id: string; company: string; role: string; location: string; status: ApplicationStatus;
  deadline: string; oa: string; interview: string; outcome: string; notes: string; createdAt: string;
}

export interface ResearchPaper {
  id: string; title: string; authors: string; venue: string; year: string; url: string;
  status: 'to-read' | 'reading' | 'read';
  problem: string; gap: string; method: string; results: string; limitations: string; novelty: string; futureWork: string;
  createdAt: string;
}
export interface Experiment { id: string; date: string; title: string; hypothesis: string; setup: string; result: string; createdAt: string }

export interface Course { id: string; code: string; name: string; credits: number; grade: string; semester: string; createdAt: string }
export interface AcademicItem { id: string; kind: 'exam' | 'assignment' | 'lab'; course: string; title: string; due: string; status: 'pending' | 'submitted' | 'graded'; createdAt: string }

export interface ObjectiveItem { id: string; text: string; done: boolean }

export type TodaySlot = 'build' | 'learn' | 'research' | 'career' | 'review';
export interface TodaySlotState { slug: string | null; locked: boolean; done: boolean; seed: number }
export interface TodayState {
  date: string;
  slots: Record<TodaySlot, TodaySlotState>;
}
export interface TodayConfig { domains: Record<TodaySlot, string[]> }

export interface Activity { at: string; kind: string; label: string; slug?: string }

export type ThemePref = 'light' | 'dark' | 'system';

export interface AppState {
  version: 1;
  docStatus: Record<string, DocProgress>;
  checks: Record<string, boolean>;
  bookmarks: string[];
  pins: string[];
  mission: string;
  weeklyObjectives: ObjectiveItem[];
  tasks: Task[];
  goals: Goal[];
  milestones: Milestone[];
  habits: Habit[];
  journal: JournalEntry[];
  decisions: Decision[];
  achievements: Achievement[];
  applications: CareerApplication[];
  projects: Project[];
  papers: ResearchPaper[];
  experiments: Experiment[];
  courses: Course[];
  academicItems: AcademicItem[];
  todayConfig: TodayConfig;
  today: TodayState | null;
  activity: Activity[];
  theme: ThemePref;
}
